cat << 'EOF' > /tmp/puppeteer-run/capture.js
const puppeteer = require('puppeteer');
const path = require('path');

(async () => {
  try {
    const browser = await puppeteer.launch({
      headless: true,
      args: ['--no-sandbox', '--disable-setuid-sandbox']
    });
    const page = await browser.newPage();

    // Set viewport matching the HTML body size
    await page.setViewport({
      width: 1414,
      height: 2000,
      deviceScaleFactor: 2 // Crisp render
    });

    const fileUrl = 'file://' + path.resolve('/tmp/poster.html');
    console.log(`Loading ${fileUrl}...`);

    await page.goto(fileUrl, { waitUntil: 'networkidle0' });

    // Ensure fonts are loaded and charts are rendered
    await page.evaluate(() => document.fonts.ready);
    await new Promise(resolve => setTimeout(resolve, 500)); // Small buffer for Chart.js

    console.log('Taking screenshot...');
    await page.screenshot({ 
      path: '/app/output/final_poster.png',
      fullPage: true 
    });

    console.log('Screenshot saved to /app/output/final_poster.png');
    await browser.close();
  } catch (err) {
    console.error('Error:', err);
    process.exit(1);
  }
})();
EOF
